# Ratios and calculated lines whose name would otherwise match their parts (BUN / Creatinine Ratio -> creatinine): label pattern -> entry.
RATIOS: dict[str, tuple[str, str, str, str, str]] = {
    r"bun\s*/\s*creatinine": ("BUN/Creatinine Ratio", "BUN compared with creatinine, to tell kidney from fluid causes.",
        "The ratio of urea nitrogen to creatinine helps sort out why either one is off, such as dehydration versus kidney disease.",
        "Above range often means dehydration, a high-protein diet, bleeding in the gut, or reduced blood flow to the kidneys.",
        "Below range can come from a low-protein diet, liver disease or overhydration."),
    r"albumin\s*/\s*globulin|\ba\s*/\s*g\b": ("Albumin/Globulin Ratio", "Albumin compared with the other blood proteins.",
        "The ratio shows whether the main blood proteins are in balance. It is a screen, not a diagnosis.",
        "Above range can come from low globulins, such as in some immune deficiencies.",
        "Below range can come from low albumin or high globulins: liver or kidney disease, chronic inflammation or infection."),
    r"globulin": ("Globulin, Total", "The blood proteins other than albumin, including antibodies.",
        "Globulins carry hormones and fats and include the antibodies of the immune system.",
        "Above range can come from chronic inflammation, infection, liver disease or a blood-protein disorder.",
        "Below range can come from an immune deficiency, kidney protein loss or poor nutrition."),
    r"chol\w*\s*/\s*hdl|ldl\s*/\s*hdl": ("Cholesterol/HDL Ratio", "Total (or LDL) cholesterol compared with HDL.",
        "A lower ratio means a larger share of the cholesterol is the protective kind.",
        "Above range goes with a higher long-term heart risk: more of the cholesterol is the harmful kind.",
        "Below range is favorable."),
}
RATIO_PATTERNS = {re.compile(rx): entry for rx, entry in RATIOS.items()}


def lookup(label: str) -> dict | None:
    """The reference entry for a lab result called `label`, or None. {"name", "short", "about", "high", "low"}."""
    lowered = label.lower()
    for pattern, entry in RATIO_PATTERNS.items():
        if pattern.search(lowered):
            return _as_dict(entry)
    if "ratio" in lowered:
        return None
    topics = result_topics(label)
    for topic in INFO:                              # dict order puts the specific topics before the broad ones
        if topic in topics:
            return _as_dict(INFO[topic])
    return None


def _as_dict(entry: tuple[str, str, str, str, str]) -> dict:
    name, short, about, high, low = entry
    return {"name": name, "short": short, "about": about, "high": high, "low": low}
